// ── Search ───────────────────────────────────────────────────────────────────
export type IndiaCity = { name: string; state: string; lat: number; lng: number };

// Big cities float to the top when several names match ("Nag" → Nagpur first).
const MAJOR = new Set([
  "mumbai","delhi","new delhi","bengaluru","bangalore","hyderabad","ahmedabad","chennai","kolkata","pune",
  "surat","jaipur","lucknow","kanpur","nagpur","indore","thane","bhopal","visakhapatnam","patna","vadodara",
  "ghaziabad","ludhiana","agra","nashik","faridabad","meerut","rajkot","varanasi","srinagar","aurangabad",
  "dhanbad","amritsar","navi mumbai","allahabad","prayagraj","ranchi","howrah","coimbatore","jabalpur",
  "gwalior","vijayawada","jodhpur","madurai","raipur","kota","guwahati","chandigarh","solapur","mysore",
  "mysuru","gurgaon","gurugram","noida","bhubaneswar","amravati","akola","kolhapur","dehradun","kochi",
  "thiruvananthapuram","nanded","jalgaon","yavatmal","wardha","latur","ahmednagar","sangli","goa","panaji",
]);

/** Up to `limit` Indian cities whose name starts with (then contains) the text. */
export function searchIndiaCities(text: string, limit = 8): IndiaCity[] {
  const q = text.trim().toLowerCase();
  if (q.length < 2) return [];
  const starts: IndiaCity[] = [];
  const contains: IndiaCity[] = [];
  for (const [name, si, lat, lng] of INDIA_CITIES) {
    const n = name.toLowerCase();
    const idx = n.indexOf(q);
    if (idx < 0) continue;
    const item = { name, state: INDIA_STATES[si] || "", lat, lng };
    (idx === 0 ? starts : contains).push(item);
  }
  const rank = (a: IndiaCity, b: IndiaCity) =>
    (MAJOR.has(b.name.toLowerCase()) ? 1 : 0) - (MAJOR.has(a.name.toLowerCase()) ? 1 : 0) ||
    a.name.length - b.name.length;
  return [...starts.sort(rank), ...contains.sort(rank)].slice(0, limit);
}
